<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>日历</title>
    <style>
        /* 自定义字体与主容器样式 */
        @font-face {
            font-family: 'NotoSansCJKsc-Bold';
            src: url('https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@700&display=swap');
            font-style: normal;
            font-weight: bold;
            font-display: swap;
        }

        /* 黑夜主题 */
        .calendar-wrapper.night-mode {
            background-color: #2a2a3a;
            border: 1px solid #4a4a6a;
            color: #d0d0e0;
        }

        /* 白天主题 */
        .calendar-wrapper.day-mode {
            background-color: #f8f4ed;
            border: 1px solid #8c785d;
            color: #5c4d3a;
        }

        .calendar-wrapper {
            border-radius: 6px;
            margin: 5px auto;
            padding: 0;
            box-sizing: border-box;
            overflow: hidden;
            font-family: 'Microsoft YaHei', 'Noto Sans SC', sans-serif;
            position: relative;
        }

        /* 日历折叠按钮样式 */
        .details-calendar-button {
            border: none;
            margin: 0;
            padding: 0;
            font-family: 'Microsoft YaHei', 'Noto Sans SC', sans-serif;
        }

        /* 黑夜模式按钮样式 */
        .night-mode .details-calendar-button {
            color: #d0d0e0;
        }

        /* 白天模式按钮样式 */
        .day-mode .details-calendar-button {
            color: #5c4d3a;
        }

        .details-calendar-button > summary {
            display: flex;
            align-items: center;
            width: 100%;
            cursor: pointer;
            font-weight: bold;
            list-style: none;
            outline: none;
            image-rendering: pixelated;
            -webkit-font-smoothing: none;
            -moz-osx-font-smoothing: grayscale;
            transition: all 0.1s ease-in-out;
            position: relative;
            top: 0;
            left: 0;
            box-sizing: border-box;
        }
        .details-calendar-button > summary::-webkit-details-marker,
        .details-calendar-button > summary::marker {
            display: none;
            content: '';
        }

        /* 日历图标样式 */
        .calendar-icon {
            margin-right: 6px;
            font-size: 1.1em;
        }

        .night-mode .calendar-icon {
            color: #6ba8e0;
        }

        .day-mode .calendar-icon {
            color: #5b99c9;
        }

        /* 黑夜模式按钮状态 */
        .night-mode .details-calendar-button:not([open]) > summary {
            padding: 4px 8px 5px 8px;
            font-size: 16px;
            line-height: 1.2;
            margin-bottom: 0;
            background-color: #3a3a4a;
            border: 1px solid #4a4a6a !important;
            border-radius: 5px;
            box-shadow: 
                0 4px 8px rgba(0, 0, 0, 0.3), 
                0 2px 4px rgba(0, 0, 0, 0.2),
                inset 0 1px 0 rgba(60, 60, 80, 0.2) !important;
            filter: none;
            justify-content: flex-start;
        }
        .night-mode .details-calendar-button:not([open]) > summary:hover {
            background-color: #454555;
            box-shadow: 
                0 6px 12px rgba(0, 0, 0, 0.4), 
                0 3px 6px rgba(0, 0, 0, 0.3),
                inset 0 1px 0 rgba(60, 60, 80, 0.3);
        }
        .night-mode .details-calendar-button[open] > summary {
            padding: 10px 8px;
            font-size: 18px;
            line-height: initial;
            margin-bottom: 5px;
            border: 1px solid #4a4a6a;
            border-radius: 5px;
            background-color: #323242;
            justify-content: flex-start;
            box-shadow:
                inset 1px 1px 0px 1px #404050,
                inset -1px -1px 0px 1px #2a2a3a;
            filter: drop-shadow(1px 1px 0px rgba(20, 20, 30, 0.5));
            font-weight: 600;
        }

        /* 白天模式按钮状态 */
        .day-mode .details-calendar-button:not([open]) > summary {
            padding: 4px 8px 5px 8px;
            font-size: 16px;
            line-height: 1.2;
            margin-bottom: 0;
            background-color: #f0d9b5;
            border: 1px solid #8c785d !important;
            border-radius: 5px;
            box-shadow: 
                0 4px 8px rgba(92, 77, 58, 0.2), 
                0 2px 4px rgba(92, 77, 58, 0.1),
                inset 0 1px 0 rgba(255, 255, 255, 0.3) !important;
            filter: none;
            justify-content: flex-start;
        }
        .day-mode .details-calendar-button:not([open]) > summary:hover {
            background-color: #e6ccaa;
            box-shadow: 
                0 6px 12px rgba(92, 77, 58, 0.3), 
                0 3px 6px rgba(92, 77, 58, 0.2),
                inset 0 1px 0 rgba(255, 255, 255, 0.4);
        }
        .day-mode .details-calendar-button[open] > summary {
            padding: 10px 8px;
            font-size: 18px;
            line-height: initial;
            margin-bottom: 5px;
            border: 1px solid #8c785d;
            border-radius: 5px;
            background-color: #d9bda0;
            justify-content: flex-start;
            box-shadow:
                inset 1px 1px 0px 1px #e6ccaa,
                inset -1px -1px 0px 1px #bfae98;
            filter: drop-shadow(1px 1px 0px rgba(92, 77, 58, 0.3));
            font-weight: 600;
        }

        .details-calendar-button > summary:active {
            padding: 10px 8px;
            font-size: 18px;
            line-height: initial;
            border-radius: 5px;
            justify-content: flex-start;
            margin-bottom: 5px;
            font-weight: 600;
        }

        /* 黑夜模式点击状态 */
        .night-mode .details-calendar-button > summary:active {
            background-color: #323242;
            box-shadow:
                inset 1px 1px 0px 1px #404050,
                inset -1px -1px 0px 1px #2a2a3a;
            filter: drop-shadow(1px 1px 0px rgba(20, 20, 30, 0.5));
            border: 1px solid #4a4a6a;
        }

        /* 白天模式点击状态 */
        .day-mode .details-calendar-button > summary:active {
            background-color: #d9bda0;
            box-shadow:
                inset 1px 1px 0px 1px #e6ccaa,
                inset -1px -1px 0px 1px #bfae98;
            filter: drop-shadow(1px 1px 0px rgba(92, 77, 58, 0.3));
            border: 1px solid #8c785d;
        }

        /* 日历内容区域 */
        .calendar-content {
            padding: 10px;
            border-radius: 5px;
            position: relative;
            z-index: 1;
            overflow-y: auto;
        }

        /* 黑夜模式内容区域 */
        .night-mode .calendar-content {
            background-color: #2d2d3d;
            border: 1px solid #3a3a4a;
        }

        /* 白天模式内容区域 */
        .day-mode .calendar-content {
            background-color: #ede4d3;
            border: 1px solid #bfae98;
        }

        /* 日历标题区域，加入切换按钮 */
        .calendar-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 10px;
            padding-bottom: 5px;
        }

        /* 黑夜模式标题边框 */
        .night-mode .calendar-header {
            border-bottom: 1px solid #3a3a4a;
        }

        /* 白天模式标题边框 */
        .day-mode .calendar-header {
            border-bottom: 1px solid #bfae98;
        }

        .calendar-title {
            font-size: 18px;
            font-weight: bold;
        }

        .calendar-info {
            font-size: 16px;
            display: flex;
            align-items: center;
            gap: 10px;
        }

        /* 昼夜模式切换按钮样式 */
        #theme-toggle {
            border: none;
            border-radius: 15px;
            padding: 5px 10px;
            cursor: pointer;
            font-size: 14px;
        }

        /* 黑夜模式按钮 */
        .night-mode #theme-toggle {
            background: #4a4a6a;
            color: #d0d0e0;
        }
        .night-mode #theme-toggle:hover {
            background: #5a5a8a;
        }

        /* 白天模式按钮 */
        .day-mode #theme-toggle {
            background: #d9c8b3;
            color: #5c4d3a;
        }
        .day-mode #theme-toggle:hover {
            background: #e6ccaa;
        }

        /* 日历表格样式 */
        .calendar-grid {
            display: grid;
            grid-template-columns: repeat(7, 1fr);
            gap: 2px;
            position: relative;
            z-index: 2;
        }

        /* 星期标题 */
        .weekday {
            text-align: center;
            padding: 5px;
            font-weight: bold;
        }

        /* 黑夜模式星期标题 */
        .night-mode .weekday {
            color: #d0d0e0;
            background-color: #353545;
        }

        /* 白天模式星期标题 */
        .day-mode .weekday {
            color: #5c4d3a;
            background-color: #d9c8b3;
        }

        /* 日期单元格 */
        .day {
            padding: 5px;
            position: relative;
            display: flex;
            flex-direction: column;
            cursor: pointer;
        }

        /* 黑夜模式日期单元格 */
        .night-mode .day {
            background-color: #2a2a3a;
            border: 1px solid #3a3a4a;
        }

        /* 白天模式日期单元格 */
        .day-mode .day {
            background-color: #f5f0e1;
            border: 1px solid #bfae98;
        }

        /* 空白单元格 */
        .day.empty {
            border: 1px solid transparent;
        }

        /* 黑夜模式空白单元格 */
        .night-mode .day.empty {
            background-color: #252535;
        }

        /* 白天模式空白单元格 */
        .day-mode .day.empty {
            background-color: #ede4d3;
        }

        .day-number {
            font-size: 14px;
            text-align: left;
            width: 100%;
            height: 20px;
        }

        /* 黑夜模式日期数字 */
        .night-mode .day-number {
            color: #8a8aaa;
        }

        /* 白天模式日期数字 */
        .day-mode .day-number {
            color: #8c785d;
        }

        /* 当前日期高亮 */
        .current-day {
