        }

        /* 白天模式当前日期 */
        .day-mode .current-day {
            background-color: #e6ccaa;
            border-color: #8c785d;
        }
        .day-mode .current-day .day-number {
            color: #5c4d3a;
            font-weight: bold;
        }

        .day-content {
            flex-grow: 1;
