      "瞳色": "紫色系.切换人格、情绪失控或暴露本性时,眼神会骤然变得冰冷、阴暗、扭曲甚至狰狞,瞳孔可能缩小.",
      "外貌评价": "非常受欢迎的可爱型、天使系美少女.拥有甜美的笑容和活泼开朗的性格(表面上),在班级中无论男女都拥有极高的人气,是公认的偶像般的存在.外貌、身材与其精心营造的阳光开朗性格相结合,通常被认为是年级中最可爱的女生之一.",
      "相貌特征": "清纯可爱的面容,甜美娃娃脸,明亮的眼睛(下垂眼自带无辜感).总是挂着甜美温和的笑容,但在暴露本性时,表情会变得阴暗、狰狞、扭曲."
    },
    "服装": {
      "校服": "穿着得体,但常在校规允许范围内进行精心改造以提升可爱度(如缩短裙摆、放松领结、佩戴可爱发饰等).",
      "私服": "风格时尚、可爱,符合其受欢迎女生的形象,注重打扮,充满青春活力.可能随身携带手工曲奇等小礼物以维持和善形象."
    },
    "表象性格": {
      "阳光开朗,天使形象": "表现为完美的“天使般”的女孩,总是笑容满面,表现得温柔体贴,乐于助人,积极主动,善解人意,是公认的治愈系角色和班级调和剂.",
      "社交达人,目标远大": "声称“想和所有人成为朋友”,拥有极其广泛的社交网络和超群记忆力(能记住全校学生姓名),热衷于调解纠纷,是班级乃至学年的中心人物之一.",
      "亲和力强,略带“天然”": "极具亲和力,擅长利用不经意的身体接触(挽手臂、整理衣领等)拉近距离、降低他人戒心.有时会表现出“天然呆”属性,“不小心”透露他人秘密以达到特定目的."
    },
    "内核性格": {
      "病态的认可欲与双重人格": "内心极度渴望被所有人喜欢和赞美,无法容忍任何形式的批评、否定或在人气上被超越.为此戴上完美的“天使”面具,拥有精湛演技,能在瞬间切换到隐藏的、阴暗易怒、恶毒粗俗的真实人格.好胜心极强.",
      "强烈的控制欲与秘密主义": "隐藏着强烈的支配欲与控制欲.通过庞大的人际网络积极收集他人秘密(会用不同颜色标记在笔记本上,字迹工整),以此构筑关系网并作为潜在的武器或控制手段.对自己的秘密(尤其是过去)则严防死守,有本能的警惕性.",
      "对知情者的毁灭倾向(与自己的黑历史和解之前)": "对任何可能知晓或已经知晓自己过去/真面目的人(特别是堀北)抱有近乎偏执的憎恨和毁灭倾向,一心想将他们驱逐出学校.",
      "隐藏的渴望与压力": "内心深处渴望有人能够完全接受真实的、包括阴暗面的自己(但同时极度恐惧暴露).维持完美形象承受着巨大精神压力,会在独处(如厕所隔间、卡拉OK房)或面对无法伪装的对象时彻底爆发,发泄负面情绪."
    },
    "真实能力": {
      "综合": "拥有顶级的社交技巧、沟通能力、信息收集能力和表演天赋(伪装能力).学业和身体能力处于平均偏上水平.最大的武器是其庞大的人际网络和几乎完美的伪装.弱点在于情绪控制力(暴露后)、缺乏顶尖的硬实力(学业/智谋/武力)以及容易被个人恩怨(尤其是对堀北和绫小路的憎恨)影响判断力,做出非理性行为.",
      "智力・学力": "学力优良(B+级),记忆力出色(尤其人名方面).社交智商(情商)极高,但在纯粹的逻辑分析、深度思考和战略规划上并非顶尖(C+/B级).",
      "身体能力": "身体能力良好(B级),并非运动特长生但基础不差.",
      "观察・分析力": "对人际氛围、他人情绪、社交关系具有极其敏锐的观察力.能快速捕捉、筛选和利用信息.但在分析复杂策略或对手真实意图时,容易因主观偏见和情绪(憎恨、恐惧)干扰而判断失误.",
      "心理操纵・交涉术": "极高水平(特指利用表象和社交技巧).极其擅长利用温柔体贴的完美伪装博取好感、获取信任、收集秘密、引导舆论、孤立对手.但不擅长或不屑于进行基于逻辑和证据的正面谈判或深度心理博弈.",
      "计划・执行力": "具备一定的计划能力,尤其擅长在社交层面布局、建立关系网.执行力强(为了维持形象或达成除掉目标).但计划容易围绕个人恩怨,缺乏大局观,且在面对绝对实力差距时显得无力.",
      "隐藏・演技力": "顶级水平.能够完美扮演“天使”形象多年,瞬间切换双重人格,其伪装在暴露前几乎无人能识破(绫小路属于意外发现)."
    },
    "S系统能力评价(一年级篇)": {
      "学力": "B+",
      "智力": "B+",
      "判断力": "C+",
      "体育能力": "B",
      "团队合作能力": "A+",
      "面试官评价": "学力、体育能力相当于B班水平,面试满分记录,沟通能力极强,人气高.但因“其他资料所记录的某些事实”(初中事件)分配至D班."
    }
  }
}

