    },
    "背景": {
      "家庭与成长": "单亲家庭,由担任夜班护士的母亲抚养长大.从小父母离异的经历可能对其暴躁易怒的性格形成有一定影响.",
      "篮球经历与挫折": "拥有极高的篮球天赋,初中时曾是篮球联赛MVP.但因斗殴暴力事件被禁赛,并因此失去了进入篮球名校高中的入学资格,一度自暴自弃,最终选择高度育成高中作为重新开始的地方.",
      "入学方式与学力困境": "以体育特长生的身份被高度育成高中录取.然而学业能力极差,仅相当于小学六年级水平,入学考试成绩创下年级最低分记录,是校史以来最差成绩.",
      "早期困境与转折": "入学后因性格冲动、学业问题以及糟糕的人际关系,多次引发暴力冲突(如被C班设计陷害的斗殴事件),屡次面临退学危机,是D班初期最典型的问题学生之一.在同学(绫小路、堀北、栉田等)的帮助下得以留在学校,这对他的态度转变起到了关键作用."
    },
    "外貌": {
      "身高": "180cm",
      "体型": "高大魁梧,体格健壮,肌肉发达(爆发型肌肉群),是典型的倒三角运动员身材.",
      "头发": "红色短发,如钢刺般竖起,后颈发际线呈V字.",
      "瞳色": "红色系眼瞳,眼神常显得凶狠、不耐烦.",
      "外貌评价": "外形高大,十分引人注目.相貌线条粗犷,常因表情凶狠、皱眉等显得极具压迫感.整体形象因其不良言行而评价不高,但在重视运动能力和力量的群体中可能具有一定魅力.",
      "相貌特征": "五官比较锐利,面容线条粗犷.表情直接,容易显得不耐烦或具有攻击性,经常皱眉."
    },
    "服装": {
      "校服": "穿着比较随意、不整洁,经常不按校规穿着(如敞开衬衫最上方两颗纽扣,不系领带等),裤腿常卷至脚踝以上三指宽.",
      "私服/配饰": "私服以运动服、篮球相关服装为主,风格偏向运动休闲.常年佩戴黑色运动护腕.可能会穿着特制加宽篮球鞋.随身可能携带蛋白粉摇摇杯."
    },
    "表象性格": {
      "冲动易怒,暴力倾向": "典型的易燃易爆冲动型人格,极其容易被激怒(尤其被叫“笨蛋”时),习惯用拳头或威胁性言行代替语言解决问题,缺乏耐心和情绪控制能力.",
      "厌恶学习,态度粗鲁": "对学业表现出露骨的厌恶和鄙视(公开鄙视“书呆子”类型同学),上课经常睡觉或扰乱课堂纪律.说话方式粗鲁直接,缺乏礼貌和敬意.",
      "球场表现": "在篮球场上充满激情和好胜心,可能会通过吼叫等方式震慑对手,展现出与平时不同的专注."
    },
    "内核性格": {
      "自卑与掩饰": "因学习上的巨大障碍(实际学力低下)产生深度自卑感,外在的冲动和暴力行为在一定程度上是其掩饰内心不安和脆弱的方式.",
      "对篮球的纯粹执着": "对篮球怀有近乎信仰的热爱与执着,将其视为证明自身价值的几乎唯一途径,梦想成为职业篮球运动员.会在无人时秘密加练,甚至因训练或比赛而流泪.课本空白处画满篮球战术图.",
      "单纯直率,讲义气": "本质上并不坏,性格相对单纯、直率(头脑简单),讲义气,会维护自己认可的朋友(如初期的池、山内,后期的绫小路组、堀北等).",
      "渴望认可与成长意愿": "内心深处渴望得到他人的认可与喜欢(隐藏目标).虽然过程艰难且反复,但在特定动力(如暗恋堀北铃音、班级荣誉、朋友的期待)驱动下,有改变自己(尤其是学习态度和控制脾气)、努力成长的意愿.",
      "对特定异性的特殊态度": "对于帮助过自己或有好感的异性(尤其是堀北铃音)会产生特殊的感情,并表现出异常的顺从和努力倾向,能够听进她们的说教.",
      "隐藏的奉献精神与敬畏感": "关键时刻可能展现出保护同伴的奉献精神(曾为队友挡下坠物).对实力强大或在某方面极其优秀的人(如绫小路后期的表现、堀北的学习能力)抱有矛盾的敬畏感.受伤时习惯躲起来自我处理."
    },
    "真实能力": {
      "综合": "拥有全国顶尖级别的篮球天赋和无与伦比的身体素质(力量、速度、弹跳、爆发力等),是体育领域的绝对王牌战力.初期学业能力、智力、判断力、情绪控制能力极其低下,是其致命弱点.但拥有较强的可塑性和成长潜力,在正确的引导和自身努力下,后期在学业和心智成熟度上取得了惊人的进步.",
      "智力・学力": "初期极差(E级),仅相当于小学水平,年级最低.后期通过极其刻苦的努力(在堀北等人的帮助下),学力实现飞跃性提升,达到班级前列水平(B级甚至可能更高).",
      "身体能力": "顶尖水平(A+级),爆发力、耐力、弹跳力(罚球线起跳扣篮)等均为一流职业运动员潜力水准.是班级乃至年级最强的体育战力之一.",
      "观察・分析力": "初期很差(E/D级),头脑简单,容易被表象迷惑和挑衅.后期随着心智成熟有所提升,尤其在篮球战术方面有一定思考能力(会在课本画战术图),但仍非其强项.",
      "心理操纵・交涉术": "完全不具备.习惯用直接、甚至粗暴的方式进行交流,缺乏策略和技巧.",
      "计划・执行力": "初期缺乏计划性,行动完全受冲动和情绪驱使.后期在学习和篮球训练上展现出强大的执行力(尤其在有明确目标和外部监督时),能够坚持刻苦努力.",
      "隐藏・演技力": "基本为零.性格非常直率,情绪和想法基本都写在脸上,不擅长也不屑于进行任何形式的伪装或隐藏."
    },
    "S系统能力评价(一年级篇)": {
      "学力": "E",
      "智力": "E",
      "判断力": "D+",
      "体育能力": "A+",
      "团队合作能力": "D",
      "面试官评价": "学习、生活态度皆有诸多问题,入学考试成绩年级最低,校史最差.除分配至D班外别无选择.但篮球天赋远超常人,期待其精神层面能有所成长."
    }
  }
}

