      "成长与蜕变": "在遭受重大打击(尤其是被揭露秘密、被心理摧毁)后会陷入迷茫和自我怀疑,但具备重新振作的韧性.后期展现出惊人的成长,变得极其坚强、执着,甚至带有“粉切黑”的倾向,为了目标(包括赢得所爱之人)可以变得精明和不择手段.",
      "深情与执着": "对能够真心接受真实的自己、带自己走出阴影的人抱有深厚的爱慕之情,即使经历伤害也难以割舍,甚至愿意为此冒险和改变.后期展现出强烈的占有欲和竞争意识.",
      "领导风格隐患": "其强大的包容力和凝聚力在带来团结的同时,也可能扼杀班级内部的个性和必要的危机感,导致同学过度依赖,形成恶性循环.",
      "黑化潜质": "如果当她遇到重大挫折(所带领的班级从B班降为D班、遭到班级内的一半以上的同学不信任),尽管会消极一周时间.但她不会沉沦于失败,反而会完成惊人的蜕变,将变得更加坚强、执着,甚至不择手段."
    },
    "真实能力": {
      "综合评价": "“社交与领导力顶尖,策略与体能短板明显”—— 擅长 “凝聚人心、管理资源、建立人脉”,是 “天生的领袖”；但 “情感脆弱、过度信任、体能差”,容易被对手针对,后期通过 “自我觉醒” 弥补了部分策略短板,成为 “全面的领导者”.",
      "具体能力": {
        "领导力(团结凝聚)": "专家级,能将 “松散的 B 班” 打造成 “凝聚力最强的班级”,仅凭个人魅力就能获得 “全校学生的信任”,社交贡献度 A+(96 分)是最直接的证明.",
        "财务(点数管理)": "精通级,作为 B 班 “金库管理员”,管理数百万私人点数,从未出现差错,这种 “高度的责任心与组织能力”,让她成为班级的 “财务支柱”.",
        "智力(推理分析)": "精通级,拥有 “敏锐的观察力与逻辑推理能力”—— 在游轮考试中,准确识别 “谁是 VIP”；学术能力顶尖,与 A 班优等生水平相当.",
        "学术(学力)": "专家级,全科目成绩优异,尤其擅长 “人文、社会科学”,能轻松应对学校的学术挑战,是班级的 “学术标杆”"
      },
      "入学时的能力测试/S系统能力(一年级篇)": {
        "学力": "A- // 非常优秀 (入学测验全年级第一)",
        "智力": "A-",
        "判断力": "B",
        "体育能力": "B+",
        "团队合作能力": "A // 顶级,是班级团结的核心"
      }
    }
  }
}

