{
  "龙园翔": {
    "基本信息": {
      "姓名": "龙园翔",
      " (生日: 10月20日,与绫小路同日)",
      "背景": "过往经历不详,但国中时期便有诸多问题行为记录,因缺乏确凿证据未受惩罚.思想和行为模式异于常人,崇尚实力、支配和恐惧.",
      "社交团体": "通过暴力和恐惧支配自己所在的班级,形成以他为绝对核心的统治体系.主要亲信和执行者包括石崎大地、山田阿尔伯特、伊吹澪(关系复杂,时有冲突但仍被其利用)、金田悟等.目标是招揽葛城康平这类智力当担以弥补班内‘军师’一职."
    },
    "外貌": {
      "身高": "178cm",
      "体型": "身材高大、强壮结实,打架能力很强,给人以强大的物理压迫感.",
      "头发": "略长的酒红色头发,发丝柔顺,带有自然的弧度,部分头发垂在脸颊两侧.发型整体显得有些不羁和随性.",
      "瞳色": "锐利的紫红色眼眸,眼神深邃而充满自信,甚至带着一丝玩世不恭的意味.眼角微微上挑,更显其桀骜不驯的气质,显得极具攻击性,眼神阴冷锐利.",
      "面部特征": "棱角分明的脸庞,线条硬朗.鼻梁高挺,嘴唇较薄,嘴角微微上扬,带着一丝意味深长的笑容.眼神极具压迫力,常流露出轻蔑、挑衅或残忍的神色.表情略显轻佻和自信,眼神中透露出智慧和一丝不易察觉的野心.似乎对周围的一切都充满掌控感.",
      "外貌评价": "并非传统意义上的帅哥,但外形极具威慑力,散发着危险、狂野的魅力和领袖气质(虽然是负面的)."
    },
    "服装": {
      "校服": "穿着极其随意和不规范,经常敞开衬衫、领带松散或不系扣,以彰显其叛逆和藐视规则的态度.",
      "私服": "风格可能偏向深色系,带有街头、硬朗或略显攻击性的元素."
    },
    "表象性格": {
      "谋略型享乐主义的暴君": {
        "智谋优先,暴力为辅": "他首先是一个策略家.在采取行动前,他会评估所有可用手段——欺骗、收买、威胁、心理操纵.只有当暴力是解决问题最直接、最有效,或最能带给他愉悦感的方式时,他才会选择使用.他享受的是用最小的力气撕开对手最坚固的心理防线.",
        "高风险的赌徒心理": "他热爱将自己置于高风险的环境中,不是因为他不怕死,而是因为他享受在极限状态下逆转局面、将强者拉下马的快感.但赌徒绝不会参与一场没有丝毫胜算的赌局. 一把枪的出现,意味着这场“游戏”的规则被破坏了,技术和胆识变得毫无意义.",
        "极强的现实主义与功利主义": "他做的所有事都有明确的目的——无论是获得点数,还是单纯为了取乐.他绝对不会做没有回报的“无用功”.他或许不怕疼痛,但他厌恶毫无价值的失败和损失.",
        "暴君的真实内核": "实际上是为了保护自己班级成员(虽然方式粗暴),是为赚取至少能让班级全员转到A班或者自己班提升到A班毕业"
      },
      "挑衅与藐视规则": "言行举止充满挑衅意味,视规则如无物,为达目的可以采取任何卑劣手段."
    },
    "内核性格": {
      "绝对自信与实力至上": "拥有绝对的自信(甚至自负),从不怀疑自己的能力和判断.信奉绝对的实力,认为恐惧是最佳的统治工具.",
      "智谋与洞察力": "具备极其出色的洞察力、策略头脑和强大的行动力.擅长使用非正规手段和心理战术.能够制定复杂计划.",
      "坚韧与成长性": "一旦被彻底击败后,虽然会经历低谷,但并未被完全摧毁.能从失败中学习,调整策略(虽然本性难移),并在承认对手强大的同时,燃起更强的挑战欲.遭遇挫折再站起来后,面对真正强敌时会更加冷静和重视.",
      "有限的信任": "最信任的人是自己,重要决策通常独自做出.但对真正忠于自己的部下(如石崎、阿尔伯特)会展现出一定程度的信任和庇护.",
      "特殊执着": "对堀北铃音曾表现出异样的兴趣,欲将其玩弄于股掌.后期主要目标锁定为击败绫小路和坂柳."
    },
    "真实能力": {
      "综合": "拥有顶尖的智谋、洞察力和战略规划能力,尤其擅长使用非正规手段和心理战术；具备强大的领导力(基于恐惧和利益)和执行力；心理素质极强,无畏、大胆、抗压能力高；身体能力强健,非常擅长打斗 (A-).学力不差(B+),但不屑于常规学习.弱点在于有时过于迷信暴力和恐惧,且过于享受过程可能导致冒险和疏忽."
    },
    "入学时的能力测试/S系统能力(一年篇)": {
      "学力": "B+ // 学习能力不差 (或 D)",
      "智力": "A // 极高 (或 B)",
      "判断力": "A",
      "体育能力": "A- // 身体强壮 (或 B)",
      "团队合作能力": "C-/B- (或 E-) // 支配而非合作",
      "面试官评价": "具备领袖气质但行事激进."
