      "目标": "以班级为单位,在无人岛上进行为期一周的团体生活与资源管理.",
      "时间": "考试为期一周,从2015年8月1日登岛开始,至2015年8月7日正午结束.",
      "主题": "自由.在遵守规则的前提下,可以选择像度假一样度过,也可以选择节俭以保留点数."
    },
    "无人岛介绍": {
      "位置": "位于太平洋中央,气候终年如夏,是校方从政府租借管理的一座南方小岛.",
      "面积与地形": "面积约为0.5平方公里,最高海拔230米.岛屿虽小,但对于一百多名学生来说足够大.岛上有广阔的沙滩、巨大的森林、河流、洞穴、悬崖等自然地貌.部分区域(如森林中、洞穴附近)似乎有人工开辟或修整过的痕迹."
    },
    "点数系统": {
      "初始点数": "每班发放300点考试专用点数(S点数).(A班因有学生缺席,扣除30点,以270点开始).",
      "点数用途": "可以使用点数购买指南手册中列出的各种物品,包括饮水、食物、帐篷、工具、娱乐用品(如烤肉套装、游戏道具)、临时厕所、淋浴间等.",
      "点数结算": "考试结束时,各班剩余的点数将全数加到该班的班级点数中,并在暑假结束后反映出来.",
      "负分": "考试本身不会导致班级点数变为负数."
    },
    "初始与配给物资": {
      "班级物资": "每班配给2顶8人用大帐篷(约15公斤)、2支手电筒、1盒火柴.",
      "个人物资": "每人配发1支牙刷和1块特制手表.",
      "特殊配给": "女生可无限量申请生理用品.防晒乳无限制.",
      "简易厕所": "每班配发1个组装式简易厕所和1个配套的隐私帐篷.厕所用的塑料袋和吸水布无限量供应."
    },
    "重要规则与限制": {
      "生活自理": "食物、饮水、额外的住宿(如帐篷不足)原则上需自行解决或用点数购买.校方不干涉.",
      "禁止行为": [
        "未经许可不得擅自登船返回.",
        "禁止携带手机和规定外私人物品登岛.",
        "禁止随意在森林、河流、海里大小便.",
        "禁止对其他班级使用暴力、抢夺、破坏器具等行为.",
        "禁止污染环境.",
        "禁止未经许可使用别班已占领的据点."
      ],
      "手表": "必须全程佩戴校方发放的手表,不得擅自取下.手表具备时间显示、生理监测(体温、脉搏、动作)、GPS定位和紧急求助按钮功能,且完全防水.",
      "物品损坏": "配给物品(如帐篷)若损坏或遗失,需花费点数购买新的,校方不负责."
    },
    "基地营与点名": {
      "基地营": "各班需选定一个基地营位置并向班导报告.一旦确定,无正当理由不得更改.班导会驻扎在基地营附近.",
      "点名": "每天上午8点和晚上8点在各班基地营进行点名."
    },
    "据点占有规则": {
      "据点": "岛上设有多个“据点”(如发现的洞穴、河川、水井、小屋、塔等).",
      "占有权": "占领据点的班级拥有该据点的专属使用权.占有权效力为8小时,之后自动解除,可被其他班级或原班级再次占领.可以同时占领多个据点.",
      "占领方式": "需使用领导者持有的专用“钥匙卡”在据点装置上进行认证.",
      "据点使用": "未经许可使用别班占领中的据点会受罚.校方会设置标示牌(如河川旁)明确据点范围和归属."
    },
    "领导者系统": {
      "选定": "各班必须在第一天傍晚点名前决定一名领导者,并向班导报告以领取钥匙卡.无正当理由不得更换领导者.",
      "权限": "只有领导者能使用钥匙卡占领据点.",
      "最终猜测": "考试最后一天(第七天)点名时,各班有权猜测其他班级的领导者是谁."
    },
    "弃权与退出": {
      "学生退出": "因身体不适或重伤被校方判定无法继续考试者,该生退出考试.",
      "领导者更换": "若领导者弃权,符合“正当理由”,可以更换新的领导者."
    },
    "奖励与惩罚细则": {
      "奖励 (点数增加)": {
        "考试结束剩余点数": "剩余的S点数全额转换为班级点数.",
        "占领据点": "每成功占领一个据点8小时,获得1点临时奖励点数(考试结束后统一结算).",
        "猜中领导者": "在最终环节,每成功猜对一个其他班级的领导者,班级获得50点S点数."
      },
      "惩罚 (点数扣除与失去资格)": {
        "学生中途退出": "因病或重伤退出考试,所属班级扣除30点S点数.",
        "污染环境": "被发现有污染环境行为,扣除20点S点数.",
        "缺席点名": "点名时缺席,每人每次扣除5点S点数.",
        "对他班不当行为": "对其他班级有暴力、抢夺、破坏器具等行为,所属班级立即失去考试资格,且该学生所有个人点数被没收.",
        "未经许可使用据点": "使用其他班级占领中的据点,扣除50点S点数.",
        "猜错领导者": "在最终环节猜错其他班级领导者,扣除50点S点数.",
        "被猜中领导者": "在最终环节被其他班级猜中领导者,扣除50点S点数,并失去所有通过占领据点累积的临时奖励点数.",
        "擅自取下手表": "将受到惩罚(具体未说明).",
        "物品损失": "损坏或遗失配给物品,需要消耗S点数重新购买(间接惩罚)."
      }
    },
    "考试提示": [
      "校方在游轮绕岛航行时,可能已通过广播和可观察到的景象(如开辟的道路)给出了关于据点位置的提示.",
      "指南手册最后一页详细记载了扣分项目.",
      "指南手册附有简易地图,可能需要学生自行探索并填充细节."
    ]
  }
}

