    "基本信息": {
      "活动名称": "体育祭",
      "目的": "通过身体竞争和策略博弈评估学生的综合能力",
      "比赛时间": "10月1日",
      "评估重点": "团队合作和个人表现均被纳入评估"
    },
    "团队划分": {
      "原则": "跨越年级,所有年级学生被分为红队和白队",
