      "白队组成": "B班和C班"
    },
    "比赛类别": [
      {
        "名称": "个人项目",
        "参与要求": "全体参与项目(所有学生必须参加)",
        "内容": [
          "短跑(男子100米、女子100米、男子400米、女子400米)",
          "长跑(男子1500米、女子1500米)"
        ],
        "计分规则": {
          "计入对象": "个人所在班级所属的团队(红队/白队)",
          "积分明细": [
            {"名次": "第1名", "积分": 25},
            {"名次": "第2名", "积分": 20},
            {"名次": "第3名", "积分": 15},
            {"名次": "第4名", "积分": 10},
            {"名次": "第5名", "积分": 5},
            {"名次": "其余名次", "积分": 0}
          ]
        }
      },
      {
        "名称": "推荐参与项目",
        "参与要求": "各班可选定特定学生参加(班级为单位)",
        "内容": [
          "5人篮球赛(男子篮球、女子篮球,三局两胜制)"
        ],
        "计分规则": {
          "计入对象": "班级所在的团队(红队/白队)",
          "积分明细": [
            {"名次": "第1名", "积分": 50},
            {"名次": "第2名", "积分": 40},
            {"名次": "第3名", "积分": 30},
            {"名次": "第4名", "积分": 20},
            {"名次": "第5名", "积分": 10},
            {"名次": "其余名次", "积分": 0}
          ]
        }
      },
      {
        "名称": "团队比赛",
        "参与要求": "各班以班级为单位参与(跨年级协作)",
        "内容": [
          {
            "项目": "400米接力赛(决赛)",
            "人数要求": "各班派出10人",
            "特点": "积分加倍(三倍积分)"
          },
          {
            "项目": "男女两人三足",
            "人数要求": "50米往返跑接力(5名女生、5名男生组成5组)"
          }
        ],
        "计分规则": {
          "计入对象": "班级所在的团队(红队/白队)",
          "接力赛(三倍积分)": [
            {"名次": "第1名", "积分": 150},
            {"名次": "第2名", "积分": 120},
            {"名次": "第3名", "积分": 90},
            {"名次": "第4名", "积分": 60},
            {"名次": "第5名", "积分": 30},
            {"名次": "其余名次", "积分": 0}
          ],
          "两人三足": [
            {"名次": "第1名", "积分": 25},
            {"名次": "第2名", "积分": 20},
            {"名次": "第3名", "积分": 15},
            {"名次": "第4名", "积分": 10},
            {"名次": "第5名", "积分": 5},
            {"名次": "其余名次", "积分": 0}
          ]
        }
      }
    },
    "体育祭结算": {
      "团队最终计分": "个人项目的累计积分 + 推荐参与项目的累计积分 + 团队比赛的累计积分",
      "胜负判定": "红队对白队的最终总积分决定胜负",
      "团队点数增减": {
        "输队惩罚": "输队所有班级总计减300班级点数(可能按班级均分).",
        "胜队奖励": "胜队所有班级总计加600班级点数(可能按班级均分)."
      },
      "班级排名奖励": {
        "奖励对象": "体育祭总积分最高的班级(所有年级)",
        "奖励点数": "额外获得50班级点数"
      },
      "个人奖励": {
        "奖励对象": "个人项目的前3名",
        "奖励点数": "分别获得个人点数:150万、120万、90万"
      }
    }
  }
}

