{
  "船上特别考试(“优待者”特别考试)": {
    "基本信息": {
      "名称": "船上特别考试(“优待者”特别考试)",
      "地点": "豪华客船上进行",
      "目的": "考验学生的“Thinking”(思考能力),包括分析现状、厘清课题、准备解决方案及发挥创造力的能力.",
      "时间": "2015年8月11日-14日(持续四天,直到第四天晚上9点结束)"
    },
    "分组方式": {
      "基础": "全体一年级学生(A班至D班)被比喻成十二干支(生肖),分成十二个小组.",
      "构成": "每个小组由来自不同班级的学生混合组成,通常每班派出3至5人,总计约14人左右构成一个小组.",
      "通知": "学生会被个别或小批量地召集,告知自己所属的小组名称(如“卯”组/兔组、“辰”组/龙组)以及同组的其他成员名单.",
      "分组意图": "分组并非随机,而是经过学校“严正调整”,似乎将各班代表性人物或特定类型的学生有意分配到一起."
    },
    "核心机制": {
      "优待者指定": "每个小组内会有一名学生被学校指定为“优待者”.",
      "优待者通知": "考试开始当天早上8点10分,学校会同时向所有学生发送邮件.“优待者”会通过邮件被明确告知自己已被选中.",
      "答案": "该小组“优待者”的姓名,即是本次考试该小组需要找出的“答案”.",
      "机密性": "优待者的身份分配具有规律(如学生生日、姓名首个字母等),但由于小组讨论的存在,大多数人认为只能通过讨论确定其身份."
    },
    "考试流程与日程": {
      "8月10日": {
        "18:00": "通过短信通知的方式通知学生其所在小组(分组)",
        "20:30": "分组进行本次船上特别考试的规则说明"
      },
      "8月11日 (第1天)": {
        "08:10": "各班优待者开始收到被选作优待者的短信",
        "13:00-14:00": "各组第一次小组讨论",
        "20:00-21:00": "各组第二次小组讨论"
      },
      "8月12日 (第2天)": {
        "13:00-14:00": "各组第三次小组讨论",
        "20:00-21:00": "各组第四次小组讨论"
      },
      "8月13日 (第3天)": {
        "13:00-14:00": "各组第五次小组讨论",
        "20:00-21:00": "各组第六次小组讨论"
      },
      "8月14日 (第4天)": {
        "13:00-14:00": "各组第七次小组讨论",
        "20:00-21:00": "各组第八次小组讨论",
        "21:30": "考试结果公布、计算班级点数"
      },
      "强制讨论": "小组成员每天必须在指定时间(下午1点、晚上8点)到指定房间集合两次,进行为期一小时的讨论.期间原则上不允许离开房间."
    },
    "答题规则": {
      "答题人": "只有非优待者的学生有权提交答案.",
      "答题方式": "在规定时间内,使用自己的手机将答案(优待者姓名)发送至学校指定的邮箱.",
      "机会": "每名学生只有一次答题机会.",
      "限制": "学生只能回答自己所属小组的问题,优待者本人无权提交答案."
    },
    "四种指定结果及其奖惩": {
      "1. 结果一 (全员合作成功)": {
        "条件": "在考试正式结束后(21:30-22:00),小组内除了优待者及其同班同学之外的所有人都提交了正确的优待者姓名.",
        "奖励": [
          "所有组员(包括优待者及其同班同学)获得50万个人点数.",
          "优待者本人获得额外奖励,总计获得100万个人点数.",
          "优待者所属班级的所有同学获得相同的个人点数(数值未明确)."
