    "基本信息": {
      "名称": "混合合宿特别考试",
      "目的": "促进学生“精神层面成长”,考察跨年级、跨班级人际关系和团队合作能力,以及社会基础知识.",
      "地点": "山中的林间学校设施.",
      "时间": "2016年1月4日-1月11日(为期八天七夜).",
      "参与者": "高度育成高中全体学生(一年级至三年级)."
    },
    "分组规则": {
      "分组层级": "小组(同年级内部)和大组(跨年级混合)",
      "1. 小组(同年级内部)": {
        "基础": "按年级和性别分开.",
        "数量": "每个年级的同性学生需组成 6个 “小组”.",
        "人数限制": "根据该年级该性别的总人数决定(如80人以上:每组10-15人；70-79人:9-14人等).",
        "班级混合要求": "每个小组必须包含至少两个不同班级(A/B/C/D)的学生,不允许仅由单一班级构成.",
        "形成方式": "必须通过同年级同性学生间的讨论,达到全场一致同意才能成立小组."
      },
      "2. 大组(跨年级混合)": {
        "形成": "一年级(男/女)小组分别与二年级、三年级同时成立的对应小组会合.",
        "数量": "最终形成6个跨年级(一、二、三年级)、同性别的“大组”.",
        "人数预估": "每个大组人数预计在30至45人左右."
      }
    },
    "负责人制度": {
      "选定": "每个小组(同年级)成立后,必须在次日早上前通过内部讨论选定一名“负责人”.",
      "职责与风险": "负责人承担小组未达标可能被退学的最高风险.",
      "后果": "若无法决定负责人,该小组全体成员将立即失去考试资格并可能被退学.",
      "奖励加成": "若小组获得前三名,与负责人同班的学生奖励翻倍(个人点数和贡献的班级点数)."
    },
    "活动与课程内容": {
      "形式": "小组如同临时班级,共同生活、学习.",
      "内容": "共同上课学习(道德、精神锻炼、规律等)、日常生活(煮饭、洗衣、打扫)、共同入浴、就寝、早晨课题(如清扫)、打坐(禅)、演讲、制作、长跑/道路接力赛(最后一天考试项目之一,18公里路线).",
      "限制": "每天用餐时间仅一小时允许男女生在同一餐厅接触；男女学生基本分开生活,未经允许禁止进入对方区域或外出."
    },
    "考试与评价": {
      "最终考试": "在合宿最后一天(第八天)举行综合性考试.",
      "评价方式": "以大组(跨年级组)全体成员考试的“平均分数”作为最终评价依据,并以此决定大组排名(1至6名)."
    },
    "结果、奖励与惩罚": {
      "奖励 (大组排名1-3名)": {
        "第1名": "10,000 个人点数 + 3 班级点数",
        "第2名": "5,000 个人点数 + 1 班级点数",
        "第3名": "3,000 个人点数",
        "奖励对象": "给予小组内每一位学生.",
        "奖励倍率": {
          "班级构成倍率": "基于小组内包含的不同班级数量(2班=x1,3班=x2,4班=x3).",
          "小组人数倍率": "基于小组的总人数(10人=x1,15人=x1.5等).",
          "负责人倍率": "若小组负责人与自己同班,该学生的个人点数和贡献的班级点数奖励再乘以2 (x2)."
        }
      },
      "惩罚 (大组排名4-6名)": {
        "第4名": "-5,000 个人点数",
        "第5名": "-10,000 个人点数 + -3 班级点数",
        "第6名": "-20,000 个人点数 + -5 班级点数",
        "惩罚对象": "施加于小组内每一位学生.",
        "无倍率": "惩罚点数不受班级构成或小组人数倍率影响.",
        "赤字处理": "个人或班级点数若不足扣除,会记作赤字,在未来获得点数时优先抵扣."
      },
      "退学惩罚": {
        "触发条件": "大组排名为最后一名(第6名),且该大组内的某个小组(同年级)的平均分数低于学校设定的及格标准线.",
        "惩罚对象": "该未达标小组选出的“负责人”将被勒令退学.",
        "班级连带惩罚": "每出现一名退学者,其所属班级将被额外扣除100点班级点数.",
        "负责人陪葬权": "被退学的负责人有权指定其同小组内的一名学生一同退学(需学校认定该被指定学生是导致小组分数过低的原因之一)."
      }
    },
    "退学救济措施": {
      "条件": "需同时支付2000万个人点数 和 300点班级点数.",
      "支付": "可由全班同学共同筹集个人点数.",
      "效果": "仅能取消退学处分,但退学导致的100点班级点数惩罚依然存在."
    },
    "其他规则": {
      "手机": "考试期间(约一周)禁止使用手机,抵达后会被统一回收.",
      "携带物品": "允许携带书籍、扑克牌、零食饮料、游戏机等个人物品(在允许范围内),但食品(尤其是生鲜、不易保存的)不能带入."
    }
  }
}

