        "报酬": {
          "分数奖励": "通常奖励前三名获胜者/小组相应的分数(第一名5-15分不等).",
          "物资奖励": "部分奖励可能包含食材、道具.",
          "小组人数上限提升": "从第4天开始,部分课题奖励“开放小组的最多人数”(最高上限6人)."
        }
      }
