          "单次限时": "60秒.",
          "个人缓冲时间": "每位学生有累计 90秒 的超时缓冲时间(用于整个考试).",
          "退学风险": "若个人累计超时 超过90秒,该学生将被 勒令退学."
        }
      },
      "5. 投票机制": "投票通过平板进行,完全匿名.为防作弊,选项和学生名单在屏幕上的位置会 随机变动.",
      "6. 具体课题内容": {
        "课题① (期末考对战对手选择)": {
          "内容": "选择第三学期期末考的对战班级.",
          "选项": "坂柳班 (胜+100CP) / 一之濑班 (胜+50CP) / 龙园班 (胜+0CP)."
        },
        "课题② (教育旅行地点选择)": {
          "内容": "选择预定在11月下旬举行的教育旅行目的地.(最终结果由全年级投票决定).",
          "选项": "北海道 / 京都 / 冲绳."
        },
        "课题③ (保护点数与个人点数权衡)": {
          "内容": "选择未来半年的模式:① 全班个人点数归零,随机3人获保护点数；② 全班个人点数减半,指定1人获保护点数；③ 无人获保护点数,下次笔试末5名个人点数归零.",
          "选项": "选项① (随机给予三名) / 选项② (选择一名给予) / 选项③ (不给予任何人)."
        },
        "课题④ (期末考负面规则选择)": {
          "内容": "为第二学期末的笔试选择一项负面规则施加于本班.",
          "选项": "提高难度 / 增加惩罚 / 减少报酬."
        },
        "课题⑤ (牺牲同学换取班级点数)": {
          "内容": "让同班一名同学退学,以换取100点班级点数.(若全票赞成,需后续投票指定人选).",
          "选项": "赞成 / 反对."
        }
      },
      "7. 禁止行为": {
        "禁止": [
          "严禁签订 强制他人投票 给特定选项的契约或协议.",
          "严禁通过 金钱/点数交易 来限制或购买选票.",
          "严禁与班外第三方联系进行 作弊或妨碍考试."
        ],
        "惩罚": "违反以上规定者,相关人员可能被 退学."
      },
      "8. 特殊条件": {
        "保护点数": "本次考试中,“保护点数”无效,无法用于取消因规则(如超时)导致的退学(除非支付2000万个人点数).",
        "通讯设备": "考试期间将 回收所有通讯设备 (如手机),私藏或使用被发现将导致 退学."
      }
    }
  }
}

