{
  "White Room (白房/白房子/白屋) 设定总结": {
    "1. 简介": {
      "名称": "白屋 (White Room).环境以白色为基调,寓意纯洁、无垢、完全的控制.",
      "核心目的": "执行“人材育成计划”,旨在人为地创造天才.培养出在智力、体能、知识、技能等各方面都远超常人的存在.",
      "公开说辞": "可能包装为为被遗弃儿童提供精英教育的慈善或国家级人才培养项目."
    },
    "2. 设施与环境": {
      "地点": "秘密设施,至少一处位于崎玉县深山中(利用废弃制药工厂改建),选址隐秘,交通不便.",
      "内部": "以白色为基调,洁白、无机质、高度管控.包含教室、训练室(柔道场)、温水游泳池、研究室、医务室、宿舍、监控室等.安保措施严密."
    },
    "3. 教育对象 (Subjects)": {
      "主要来源": "被父母遗弃的新生儿、政商界人士的无法公开抚养的私生子、通过非法手段或社会接收点送入的儿童.",
      "分期": "学生按“期”区分,如绫小路清隆属于第四期 (4期生)(最初有74人).",
      "标识": "早期可能只用名字称呼(如清隆、雪、志朗),避免因姓氏产生不必要的联想."
    },
    "4. 教育体系与课程": {
      "起始时间": "从婴儿期开始介入,进行全方位的“彻底教育”.",
      "核心理念": "效率至上,成果导向.强调基础的彻底掌握和应用能力的培养.摒弃一切被认为“不必要”的情感 (喜怒哀乐).",
      "课程内容": {
        "学术": "基础读写(3岁完成)到高等数学、国语、外语、经济学、政治学等.",
        "体能/武术": "游泳、柔道、空手道、拳击、截拳道等,包含高强度的实战对练.",
        "艺术/文化": "钢琴、小提琴、书道、茶道等.",
        "其他": "心理学、观察力、洞察力训练、VR模拟外界环境学习."
      },
      "教学方法": {
        "强度": "高强度 & 高密度,日程安排精确到分钟,几乎无休息时间.",
        "情感": "不鼓励甚至惩罚情感表达,目标是让孩子变得像机器一样.",
        "淘汰机制": "定期举行高难度测试.任何一次未达标者即被视为“掉队者”,会被立即淘汰(淘汰率极高).",
        "惩罚": "对未达标、反抗、或违反规则者,施加严厉的惩罚,包括体罚和精神施压.",
        "课程分级": "存在不同难度的课程体系.绫小路清隆所在的第四期被安排了实验性的β课程 (Beta Curriculum),难度远超常规,旨在探索人类潜能的极限."
      },
      "生活管理": "饮食以高效补充营养为主.健康状况被严密监控.孩子间几乎无自发交流."
    },
    "5. 工作人员 (Staff)": {
      "负责人": "绫小路笃臣(实际发起者和最高负责人).",
      "研究员/教育者": "招募在各领域有顶尖才能的“天才”(如宗谷、石田、铃悬、田渊等),负责设计和执行课程.",
      "教官 (Instructor)": "负责具体的教学和训练,态度冷酷,严格执行命令,施加惩罚毫不手软.",
      "其他人员": "医务人员、设施管理人员、安保人员."
    },
    "6. 资金来源": "主要依靠政商界人士(财阀)的秘密投资.部分资金可能来自将私生子送入白屋的“捐赠”.",
    "7. 伦理与问题 ": {
      "性质": "极端非人道,完全剥夺儿童的正常童年、家庭关爱和情感发展.",
      "高风险": "高淘汰率,后续生活状况不明.",
      "后果": "成功者虽然能力超群,但普遍缺乏正常的情感反应、共情能力和基本的社会常识.",
      "保密性": "计划高度保密,一旦曝光将引发现巨大的伦理和法律危机."
    },
    "8. 已培养的学生": {
      "四期生": "绫小路清隆",
      "五期生": "天泽一夏, 八神拓也"
    }
  }
}

