{
  "生存与淘汰的特别考试": {
    "时间": {
      "预告": "2017年1月13日班会课上由班导进行预告和规则讲解.",
      "正式考试时间": "2017年1月17日."
    },
    "具体规则": {
      "1. 参与者": "全体二年级学生 (A, B, C, D 四个班级).",
      "2. 基本形式": {
        "回合数": "共计 20回合 攻防战.",
        "攻防顺序": "前半场10回合(顺时针):堀北班 → 一之濑班 → 龙园班 → 坂柳班 → 堀北班 (循环).",
        "后半场": "10回合(逆时针):坂柳班 → 龙园班 → 一之濑班 → 堀北班 → 坂柳班 (循环)."
      },
      "3. 攻击方规则": {
        "选择课题": "从校方提供的 16个领域(如文学、历史、科学、社会、运动、演艺、音乐、经济等)中选择一个出题领域.",
        "选择难度": "默认为难度1.可花费已得分数提升难度(每提升一级花费1分,最高可选难度3).",
        "指名对象": "在3分钟内,从防御方班级中指名 5名学生 接受课题挑战.可以重复指名同一学生或同一领域.",
        "得分": "攻击方在攻击回合不直接得分."
      },
      "4. 防御方规则": {
        "得分方式": "被攻击方指名的学生若正确回答课题,则班级得 1分.",
        "保护机制": "每回合在攻击方指名后,防御方领袖可在3分钟内指定保护本班5名学生.若被攻击方指名的学生恰好在被保护名单内,则视为答对,班级得 1分.",
        "课题排除": "每位学生可在考前预先选择最多 3个不擅长的领域 进行排除.攻击方不能选择被防御方学生排除的课题进行攻击."
      },
      "5. 淘汰规则 (“淘汰”)": {
        "判定": "任何学生累计 答错3次 即被“淘汰”.",
        "状态": "淘汰者不再成为被攻击指名的对象,但仍可留在教室内参与讨论.",
        "惩罚": "每出现一名淘汰者,该班级总得分 扣1分(得分可为负数)."
      },
      "6. 领袖角色": {
        "职责": "每班选出一名领袖,负责做出所有最终决策(如攻击指名、保护指名).",
        "安全": "领袖本人不参与答题,因此不会被淘汰.",
        "退学指定权": "若班级最终排名垫底且有淘汰者,领袖必须从本班淘汰者中指定一人退学."
      },
      "7. 排名与奖惩": {
        "排名依据": "按最终得分高低排名.",
        "班级点数奖励": {
          "第一名": "班级点数 +100.",
          "第二名": "班级点数 -50.",
          "第三名": "班级点数 -50.",
          "第四名": "班级点数 -100."
        },
        "退学惩罚": "最终排名第四名的班级,如果该班有至少一名学生被淘汰,则必须由领袖从这些淘汰者中选择 一人强制退学."
      },
      "8. 特殊条件": {
        "手机使用": "除被指名学生正在答题期间外,允许所有学生随时使用手机进行交流、查阅资料或班级内部讨论.",
        "作弊/不适": "因故无法继续考试或作弊者,均视为淘汰.作弊者还会被没收已得分数.",
        "休息": "每4回合有10分钟休息时间,前半场(10回合)结束后有40分钟午休时间."
      },
      "核心要点": "结合了知识问答(领域广泛)、策略博弈(攻防预测、保护与指名)、团队合作(信息共享、领袖决策)并带有残酷退学惩罚的高压考试.手机的允许使用大大增加了信息战和即时策略调整的可能性."
    }
  }
}

