    },
    "期末考试的班级对抗元素": {
      "出题权": "每个班级需要自己思考并制作一套完整的期末考试题目(8科共400题).",
      "攻击目标指定": {
        "指名对象": "每个班级需指名一个其他班级作为自己出题的“攻击”对象.",
        "流程": "指名在小考前一天由班级代表向班导汇报.若指名重复,则通过抽签决定最终攻击对象.",
        "题目审查": "各班制作的题目需提交给校方进行严正且公平的检查(修正超出范围或无法解答的问题).",
        "后备方案": "若班级未在期限内完成题目制作,校方将提供难度偏低的预先准备好的题目.",
        "信息自由": "学生可以自由请教老师、与其他班级或年级学生商讨,甚至利用网络资源制作题目."
      },
      "班级对抗胜负与奖惩": {
        "胜负判定": "对比两个班级在对方所出题目上的全班总分,高者获胜.",
        "基础奖励": "获胜班级获得50点班级点数.",
        "互为攻击对象": "如果两个班级互为攻击对象,则胜者获得的班级点数翻倍,变为 100点."
      }
    },
    "其他重要规则": {
      "缺席处理": {
        "有正当理由": "根据过去成绩给予预估分数.",
